'use strict';
function escapeText(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const $=s=>document.querySelector(s);const people=[{name:'あなた'},{name:'ハイデ',roman:'HEIDE',tone:'静かな眼差し',quote:CHARACTER_LINES.hina.lobby,hair:'#9e644d',light:'#c68a64',dress:'#c17b73',eye:'#89513b'},{name:'ラピス',roman:'LAPIS',tone:'蒼き魔法使い',quote:CHARACTER_LINES.tsumugi.lobby,hair:'#3e5556',light:'#617774',dress:'#77978c',eye:'#467a72'},{name:'キルケー',roman:'CIRCE',tone:'不敵な魔女',quote:CHARACTER_LINES.mio.lobby,hair:'#716582',light:'#9b8cad',dress:'#9382ac',eye:'#79679e'}];
let mode=4,G=null,selected=-1,declare=false,timer=null,speed=1,sound=false,audioCtx=null;const KEY='sakura-mahjong-online-solo-v1';
function castId(i){return G?.players?.[i]?.characterId??i}
function seatPerson(i){return people[castId(i)]}
function shuffledCast(){const ids=[1,2,3];for(let n=2;n>0;n--){const j=Math.floor(Math.random()*(n+1));[ids[n],ids[j]]=[ids[j],ids[n]]}return [0,...ids]}
function characterExpression(player){return player?.riichi?'proud':player&&player.score<10000?'worried':'normal'}
function portrait(i,player=null,catalog=false){i=catalog?i:castId(i);const expression=characterExpression(player),descriptions={normal:'通常の表情',proud:['','少しだけ口元が緩んだ表情','笑顔','不敵な笑み'][i],worried:['','無表情','かなり焦った表情','歯を食いしばって悔しそうな表情'][i]};return `<span class="anime-portrait new-cast cast-${i} ${expression}" role="img" aria-label="${people[i].name}の${descriptions[expression]}"></span>`}

$('#characters').innerHTML=[1,2,3].map(i=>`<div class="character"><div class="portrait">${portrait(i,null,true)}</div><div class="details"><small>${people[i].roman}</small><h3>${people[i].name}</h3><span class="personality">${people[i].tone}</span><p>「${escapeText(people[i].quote)}」</p></div><span class="number">0${i}</span></div>`).join('');

function beep(){if(!sound)return;try{audioCtx??=new (window.AudioContext||window.webkitAudioContext)();let o=audioCtx.createOscillator(),a=audioCtx.createGain();o.type='sine';o.frequency.setValueAtTime(650,audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(320,audioCtx.currentTime+.055);a.gain.setValueAtTime(.06,audioCtx.currentTime);a.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.07);o.connect(a).connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+.08)}catch{}}
const fmt=n=>n.toLocaleString('ja-JP'),wind=i=>(i-G.dealer+4)%4,roundWind=()=>Math.floor(G.round/4);
function tilePattern(t){let n=t%9+1;const layouts={1:[[20,28]],2:[[20,14],[20,42]],3:[[10,12],[20,28],[30,44]],4:[[10,14],[30,14],[10,42],[30,42]],5:[[10,12],[30,12],[20,28],[10,44],[30,44]],6:[[10,12],[30,12],[10,28],[30,28],[10,44],[30,44]],7:[[9,9],[20,16],[31,23],[10,36],[30,36],[10,48],[30,48]],8:[[10,8],[30,8],[10,21],[30,21],[10,35],[30,35],[10,48],[30,48]],9:[[9,10],[20,10],[31,10],[9,28],[20,28],[31,28],[9,46],[20,46],[31,46]]};let shapes='';if(t<18){shapes=layouts[n].map(([x,y],k)=>{let r=n===1?14:n>=7?4.5:6,c=n===1?'#287354':n===5&&k===2||n===9&&k>=3&&k<6?'#b0443c':n===7&&k<3?'#b0443c':'#315976';return `<g class="pip" fill="none" stroke="${c}"><circle cx="${x}" cy="${y}" r="${r}" stroke-width="${n===1?3:1.7}"/><circle cx="${x}" cy="${y}" r="${r*.48}" stroke-width="1"/><circle cx="${x}" cy="${y}" r="1" fill="${c}"/></g>`}).join('')}else if(n===1){shapes='<g class="bamboo-bird"><path d="M21 30Q10 34 8 48L17 43L14 51Q28 45 28 32" fill="#27734d"/><path d="M16 18Q17 9 24 9Q30 10 28 17L24 23Q33 30 27 37Q14 40 13 29Q12 23 16 18" fill="#358666"/><path d="M18 24Q30 29 23 35Q15 36 17 29" fill="#294e75"/><path d="M27 12L35 16L27 17" fill="#bd5142"/><circle cx="24" cy="12" r="1.4" fill="#fff"/><path d="M19 8L17 4M22 8L22 3" stroke="#b94740" stroke-width="2"/><path d="M22 37L24 44L29 44M18 38L18 46L22 46" fill="none" stroke="#9b633b" stroke-width="1.7"/></g>'}else{let positions=n===3?[[20,10],[10,38],[30,38]]:n===7?[[20,7],[10,23],[30,23],[10,35],[30,35],[10,47],[30,47]]:layouts[n];shapes=positions.map(([x,y],k)=>`<g class="bamboo-stick" stroke="${n===5&&k===2||n===9&&k<3?'#b14d41':'#28704d'}" stroke-linecap="round"><path d="M${x-1.5} ${y-5}V${y+5}M${x+1.5} ${y-5}V${y+5}" stroke-width="2"/><path d="M${x-3} ${y-4}H${x+3}M${x-3} ${y}H${x+3}M${x-3} ${y+4}H${x+3}" stroke-width="1.5"/></g>`).join('')}return '<svg class="tile-art" viewBox="0 0 40 56" aria-hidden="true" focusable="false">'+shapes+'</svg>'}
function tileDoraCount(t){if(!G)return MJ.isRed(t)?1:0;return (MJ.isRed(t)?1:0)+(G.doras||[]).filter(d=>MJ.nextDora(d)===MJ.base(t)).length}
function tile(t,kind='mini',extra='',attrs=''){const bonus=extra.includes('indicator')?0:tileDoraCount(t);if(bonus)extra+=' is-dora';let actual=t,isRed=MJ.isRed(t);t=MJ.base(t);if(isRed)extra+=' aka';let suit=t<9?'man':t<18?'pin':t<27?'sou':'honor';if(t===32)suit+=' green';if(t===33)suit+=' red';if(t===31)suit+=' blank';let face=t>=9&&t<27?tilePattern(t):t<9?`<span class="num">${'一二三四五六七八九'[t%9]}</span><span class="suit">萬</span>`:`<span>${t===31?'':MJ.names[t]}</span>`;return `<${kind==='big'?'button':'span'} class="tile ${kind} ${suit} ${extra}" title="${MJ.names[actual]}${bonus?'（ドラ'+bonus+'翻）':''}" aria-label="${MJ.names[actual]}${bonus?'、ドラ'+bonus+'翻':''}" ${attrs}>${face}${bonus?'<span class="dora-badge" aria-hidden="true">'+(bonus>1?'★'+bonus:'★')+'</span>':''}</${kind==='big'?'button':'span'}>`}

function save(){try{localStorage.setItem(KEY,JSON.stringify(G))}catch{}}
function stored(){try{let d=JSON.parse(localStorage.getItem(KEY));return d&&d.players?.length===4&&d.version===2?d:null}catch{return null}}
function resumeButton(){let d=stored();$('#resume-wrap').innerHTML=d&&!d.finished?'<button id="resume" class="quiet resume">中断した対局を再開 →</button>':'';if($('#resume'))$('#resume').onclick=()=>{G=stored();enterGame();render();if(G.phase==='result')showResult();else if(G.phase==='ron')ronActions();else if(G.phase==='draw')queue(draw);else if(G.phase==='discard'&&G.turn!==0)queue(cpu);else if(G.phase==='discard'&&G.turn===0&&G.players[0].riichi&&!evaluate(0,true,G.players[0].hand.at(-1)))queue(()=>discard(G.players[0].hand.length-1))}}
document.querySelectorAll('.mode').forEach(b=>b.onclick=()=>{mode=+b.dataset.mode;document.querySelectorAll('.mode').forEach(x=>{x.classList.toggle('selected',x===b);x.querySelector('b').textContent=x===b?'◉':'○'})});
$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent='音 '+(sound?'ON':'OFF');beep()};$('#speed').onclick=()=>{speed=speed===1?2:speed===2?3:1;$('#speed').textContent='速度 ×'+speed};
function openModal(html){$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
$('#help').onclick=()=>{openModal(`<span class="badge">HOW TO PLAY</span><h2>桜日和の遊び方</h2><p>あなたとハイデ・ラピス・キルケーの4人対戦です。ポン・チー・カンに対応しています。牌を選び「打牌」、または同じ牌をもう一度押して捨てます。和了できると「ツモ」「ロン」が表示されます。</p><ul><li><b>東風戦：</b>東1局から東4局まで。<b>半荘戦：</b>東1局から南4局まで。親の和了・親の聴牌で連荘します。</li><li>25,000点開始。25,000点未満でも予定の場で終了し、0点未満で飛び終了。オーラスの和了やめ・延長戦はありません。</li><li><b>ポン・チー・大明槓・暗槓・加槓</b>に対応。チーは上家からのみ。ロンが最優先、次にポン・カン、最後にチーです。鳴いた手には役が必要で、喰いタンあり・喰い替えなしです。</li><li>カンで嶺上牌をツモり、カンドラ・裏ドラが増えます（最大4回）。加槓への槍槓、暗槓への国士無双の槍槓も判定。鳴きで一発は消えます。リーチは門前で1,000点、宣言後は自動ツモ切り。待ちと面子構成を変えない暗槓は可能です。赤五萬・赤五筒・赤五索を各1枚採用し、1枚につき1翻加算します（赤ドラだけでは和了不可）。途中流局はありません。</li><li>4面子1雀頭・七対子・国士無双を判定。リーチ、一発、門前ツモ、平和、断么九、役牌、混一色などの役、符、ドラ・裏ドラを計算します。</li><li>ダブルリーチ、天和・地和、小四喜、緑一色、清老頭、九蓮宝燈にも対応。国士無双十三面待ち・四暗刻単騎・大四喜はダブル役満で、役満の複合は合算します。</li><li>流し満貫は流局時、鳴き・カンなしで、捨て牌がすべて么九牌かつ一枚も鳴かれていない場合に成立します。複数人ならそれぞれ満貫ツモとして精算。本場を加算し、供託は親から順に最初の成立者へ。ノーテン罰符は適用せず、親が成立した場合のみ連荘します。</li><li>フリテン時はロンできません。同時ロンは放銃者から近い席を優先する頭ハネです。ノーテン罰符は合計3,000点、本場は1本300点です。</li><li>対局はこのブラウザに自動保存されます。効果音は右上から切り替えできます。</li></ul><button id="close-help" class="primary">わかりました</button>`);$('#close-help').onclick=()=>$('#modal').close()};
$('#modal').addEventListener('cancel',e=>{if(G?.phase==='result')e.preventDefault()});
$('#start').onclick=()=>{if(stored()&&!stored().finished){openModal('<h2>新しい対局を始めますか？</h2><p>中断中の対局は、新しい対局で上書きされます。</p><button id="new-confirm" class="primary">新しくはじめる</button><button id="new-cancel" class="quiet resume">戻る</button>');$('#new-confirm').onclick=()=>{$('#modal').close();start()};$('#new-cancel').onclick=()=>$('#modal').close()}else start()};
function start(){clearTimeout(timer);const initialDealer=Math.floor(Math.random()*4);G={version:2,mode,teamMode,abilitiesEnabled,abilityUsed:{},round:0,dealer:initialDealer,initialDealer,honba:0,pot:0,players:shuffledCast().map(characterId=>({characterId,name:people[characterId].name,score:25000})),log:[],finished:false};enterGame();newRound()}
function enterGame(){$('#lobby').hidden=true;$('#game').hidden=false;selected=-1;declare=false;window.scrollTo(0,0)}
function home(){clearTimeout(timer);if(G)save();$('#game').hidden=true;$('#lobby').hidden=false;resumeButton()};$('#home').onclick=home;$('#brand').onclick=e=>{e.preventDefault();if(!$('#game').hidden)home()};
function log(s){G.log.unshift(s);G.log=G.log.slice(0,40)}
function queue(fn,delay=650/speed){clearTimeout(timer);timer=setTimeout(()=>{if(!$('#game').hidden){if($('#modal').open&&G.phase!=='result')queue(fn,delay);else fn()}},delay)}
function newRound(){let deck=Array.from({length:136},(_,i)=>Math.floor(i/4));for(let i=deck.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]]}G.dora=deck.pop();G.ura=deck.pop();deck.splice(-12);G.players.forEach(p=>{p.hand=deck.splice(0,13).sort((a,b)=>a-b);p.river=[];p.riichi=false;p.ippatsu=false;p.tempFuriten=false;p.riichiFuriten=false});G.deck=deck;G.turn=G.dealer;G.phase='draw';G.lastDiscard=null;G.result=null;selected=-1;declare=false;log(`${MJ.winds[roundWind()]}${G.round%4+1}局 ${G.honba}本場が始まりました`);G.speech=seatPerson(1+(G.round%3)).name+'「'+seatPerson(1+(G.round%3)).quote+'」';render();save();queue(draw)}
function context(i,tsumo,t){return {seat:wind(i),roundWind:roundWind(),tsumo,win:t,riichi:G.players[i].riichi,doubleRiichi:!!G.players[i].doubleRiichi,firstDraw:tsumo&&G.players[i].drawCount===1&&G.players[i].river.length===0&&G.firstTurnInterrupted===false,ippatsu:G.players[i].ippatsu,last:G.deck.length===0&&!G.afterCall,dora:G.dora,ura:G.ura,doras:G.doras,uras:G.uras,melds:G.players[i].melds,rinshan:tsumo&&G.rinshan,chankan:!!G.pendingKan}}
function evaluate(i,tsumo,t){let p=G.players[i];return MJ.score(tsumo?p.hand:[...p.hand,t],context(i,tsumo,t))}
function canRon(i,t){let p=G.players[i];if(p.tempFuriten||p.riichiFuriten)return null;let w=MJ.waits(p.hand,p.melds);if(p.river.some(r=>w.includes(MJ.base(r.t))))return null;return evaluate(i,false,t)}
function draw(){if(!G.deck.length){exhaustive();return}G.phase='discard';let p=G.players[G.turn];p.hand.sort((a,b)=>a-b);p.hand.push(G.deck.pop());p.tempFuriten=false;selected=-1;declare=false;save();render();if(G.turn!==0)queue(cpu);else if(p.riichi&&!evaluate(0,true,p.hand.at(-1)))queue(()=>discard(p.hand.length-1))}
function cpu(){let i=G.turn,p=G.players[i],r=evaluate(i,true,p.hand.at(-1));if(r){finishWin(i,i,p.hand.at(-1),r);return}let visible=Array(34).fill(0);G.players.forEach(x=>x.river.forEach(r=>visible[MJ.base(r.t)]++));let idx=p.riichi?p.hand.length-1:MJ.aiDiscard(p.hand,visible,i,p.melds,G.forbidden||[]);idx=teamDiscard(i,idx);let rest=p.hand.filter((_,j)=>j!==idx);if(!teamAvoidCall(i)&&!p.riichi&&!p.melds.some(m=>m.open)&&p.score>=1000&&G.deck.length>=4&&MJ.waits(rest,p.melds).length){p.riichi=true;p.ippatsu=true;p.score-=1000;G.pot++;say(i,'riichi');log(p.name+'がリーチ');discard(idx,true)}else discard(idx)}
function discard(idx,newRiichi=false){let i=G.turn,p=G.players[i];if(G.phase!=='discard'||idx<0||idx>=p.hand.length)return;if(p.riichi&&!newRiichi&&idx!==p.hand.length-1)return;let t=p.hand.splice(idx,1)[0];if(!newRiichi)p.ippatsu=false;p.river.push({t,riichi:newRiichi});p.hand.sort((a,b)=>a-b);G.lastDiscard={i,t};G.phase='draw';selected=-1;declare=false;beep();log(p.name+'：'+MJ.names[t]+(newRiichi?'（リーチ）':''));let candidates=[];for(let n=1;n<=3;n++){let j=(i+n)%4,r=canRon(j,t);if(r)candidates.push({i:j,r})}if(candidates.length){G.ronCandidates=candidates;if(candidates[0].i===0){G.phase='ron';save();render();ronActions();return}finishWin(candidates[0].i,i,t,candidates[0].r);return}G.turn=(i+1)%4;save();render();queue(draw)}
function ronActions(){$('#status').textContent=seatPerson(G.lastDiscard.i).name+'の'+MJ.names[G.lastDiscard.t]+'でロンできます';$('#actions').innerHTML='<button id="ron" class="accent">ロン</button><button id="pass" class="quiet">見送る</button>';$('#ron').onclick=()=>finishWin(0,G.lastDiscard.i,G.lastDiscard.t,G.ronCandidates[0].r);$('#pass').onclick=()=>{G.players[0].tempFuriten=true;if(G.players[0].riichi)G.players[0].riichiFuriten=true;let other=G.ronCandidates.find(c=>c.i!==0);if(other){finishWin(other.i,G.lastDiscard.i,G.lastDiscard.t,other.r);return}G.turn=(G.lastDiscard.i+1)%4;G.phase='draw';save();render();queue(draw)}}
function finishWin(winner,from,t,r){clearTimeout(timer);let delta=[0,0,0,0],ceil=n=>Math.ceil(n/100)*100;if(winner===from){for(let i=0;i<4;i++)if(i!==winner){let pay=ceil(r.base*(winner===G.dealer||i===G.dealer?2:1))+G.honba*100;delta[i]-=pay;delta[winner]+=pay}}else{let pay=ceil(r.base*(winner===G.dealer?6:4))+G.honba*300;delta[from]-=pay;delta[winner]+=pay}delta[winner]+=G.pot*1000;G.pot=0;G.players.forEach((p,i)=>p.score+=delta[i]);G.result={type:'win',winner,from,t,r,delta,repeat:winner===G.dealer,melds:G.players[winner].melds,hand:winner===from?G.players[winner].hand.slice():[...G.players[winner].hand,t]};G.phase='result';say(winner,winner===from?'tsumo':'ron');playSfx(winner===from?'tsumo':'ron');log(seatPerson(winner).name+'が'+(winner===from?'ツモ':'ロン')+'：'+fmt(delta[winner])+'点');save();render();showCutIn(winner,winner===from?'tsumo':'ron',showResult)}
function exhaustive(){clearTimeout(timer);if(settleNagashi())return;let tenpai=G.players.map(p=>MJ.waits(p.hand,p.melds).length>0),n=tenpai.filter(Boolean).length,delta=tenpai.map(v=>n===0||n===4?0:v?3000/n:-3000/(4-n));G.players.forEach((p,i)=>p.score+=delta[i]);G.result={type:'draw',delta,tenpai,repeat:tenpai[G.dealer]};G.phase='result';say(1+G.round%3,'draw');playSfx('draw');log('流局 — '+n+'人が聴牌');save();render();showResult()}
function scoreLimitLabel(r){if(r.yakuman)return r.yakuman===1?'役満':r.yakuman===2?'ダブル役満':r.yakuman+'倍役満';if(r.han>=13)return '数え役満';if(r.base>=6000)return '三倍満';if(r.base>=4000)return '倍満';if(r.base>=3000)return '跳満';if(r.base>=2000)return '満貫';return ''}
function showResult(){let r=G.result;if(!r)return;if(r.type==='nagashi'){showNagashiResult();return;}let win=r.type==='win';openModal(`<span class="badge">${win?'HAND COMPLETE':'EXHAUSTIVE DRAW'}</span><h2>${win?seatPerson(r.winner).name+'の'+(r.winner===r.from?'ツモ':'ロン'):'流局'}</h2><p class="result-quote">${escapeText(G.speech)}</p>${win?`<div class="result-tiles">${r.hand.slice().sort((a,b)=>a-b).map(t=>tile(t)).join('')+(r.melds||[]).map(m=>'<span class="result-meld">'+m.tiles.map(t=>tile(t)).join('')+'</span>').join('')}</div><div class="yaku">${scoreLimitLabel(r.r)?'<div class="limit-title">'+scoreLimitLabel(r.r)+'</div>':''}${r.r.yaku.map(([s,n])=>s+' '+(r.r.yakuman?(n===13?'役満':n===26?'ダブル役満':(n/13)+'倍役満'):n+'翻')).join(' ／ ')}<br><b>${r.r.yakuman?scoreLimitLabel(r.r):r.r.han+'翻 '+r.r.fu+'符'}　+${fmt(r.delta[r.winner])}点</b>${G.players[r.winner].riichi?'<br>裏ドラ表示：'+G.uras.map(t=>MJ.names[t]).join('・'):''}</div>`:'<p>山の牌がなくなりました。聴牌・ノーテンに応じて点数を精算します。</p>'}${G.players.map((p,i)=>`<div class="result-row"><span>${p.name} ${win?'':r.tenpai[i]?'聴牌':'ノーテン'}</span><span>${r.delta[i]>0?'+':''}${fmt(r.delta[i])} <b>${fmt(p.score)}</b></span></div>`).join('')}<p>${r.repeat?'親が継続するため、次は連荘です。':'次の局へ進みます。'}</p><button id="next" class="primary">${isEndAfterResult()?'対局結果を見る':'次の局へ →'}</button>`);$('#next').onclick=advance}
function isEndAfterResult(){return G.players.some(p=>p.score<0)||(!G.result.repeat&&G.round+1>=G.mode)}
function advance(){$('#modal').close();if(isEndAfterResult()){finishMatch();return}if(!G.result.repeat){G.round++;G.dealer=(G.dealer+1)%4}G.honba=G.result.type==='draw'||G.result.repeat?G.honba+1:0;newRound()}
function finishMatch(){playSfx('finish');G.finished=true;let ranked=G.players.map((p,i)=>({...p,i})).sort((a,b)=>b.score-a.score||((a.i-(G.initialDealer??0)+4)%4)-((b.i-(G.initialDealer??0)+4)%4));if(G.pot){G.players[ranked[0].i].score+=G.pot*1000;ranked[0].score+=G.pot*1000;G.pot=0}save();openModal(`${G.teamMode?teamResultMarkup():''}<span class="badge">THANK YOU FOR PLAYING</span><h2>おつかれさまでした。</h2><p>${G.mode===4?'東風戦':'半荘戦'} 終了。あなたは${ranked.findIndex(p=>p.i===0)+1}位でした。</p>${ranked.map((p,i)=>`<div class="rank"><em>${i+1}</em>${p.name}<b>${fmt(p.score)} 点</b></div>`).join('')}<p>また、お茶を片手に一局。</p><button id="back-lobby" class="primary">ロビーへ戻る</button>`);$('#back-lobby').onclick=()=>{$('#modal').close();home()}}
function riichiChoices(){let p=G.players[0];if(p.riichi||p.melds.some(m=>m.open)||p.score<1000||G.deck.length<4)return [];return p.hand.map((t,i)=>MJ.waits(p.hand.filter((_,j)=>i!==j),p.melds).length?i:-1).filter(i=>i>=0)}
function render(){if(!G)return;$('#match-label').textContent=(G.mode===4?'東風戦':'半荘戦')+' · 四人麻雀';$('#round').textContent=MJ.winds[roundWind()]+' '+(G.round%4+1)+' 局';$('#wall').textContent=G.deck.length;$('#counters').textContent=G.honba+' 本場　供託 '+G.pot+' 本';$('#dora').innerHTML=G.doras.map(t=>tile(t,'mini','indicator')).join('');$('#self-score').textContent=fmt(G.players[0].score);$('#self-wind').textContent=MJ.winds[wind(0)];$('#self-riichi').textContent=G.players[0].riichi?'リーチ':'';[1,2,3].forEach(i=>{let p=G.players[i],el=$('#seat'+i);el.classList.toggle('active',G.turn===i&&G.phase==='discard');el.innerHTML=`<div class="avatar">${portrait(i,p)}</div><div class="player-meta"><span class="wind">${MJ.winds[wind(i)]}</span>${p.name}<strong>${fmt(p.score)}</strong><small>${p.riichi?'— リーチ —':'CPU · 手牌 '+p.hand.length+'枚'}</small></div>`});for(let i=0;i<4;i++)$('#river'+i).innerHTML=G.players[i].river.map(r=>tile(r.t,'mini',r.riichi?'riichi-discard':'')).join('');$('#speech').textContent=G.speech;$('#table-speech').textContent=G.speech;$('#log').innerHTML=G.log.map(s=>`<div>${escapeText(s)}</div>`).join('');renderHand();renderActions()}
function renderHand(){let p=G.players[0],active=G.phase==='discard'&&G.turn===0&&!p.riichi,choices=declare?riichiChoices():[];$('#hand').innerHTML=p.hand.map((t,i)=>tile(t,'big',(selected===i?'selected ':'')+(!G.afterCall&&p.hand.length%3===2&&i===p.hand.length-1?'drawn':''),`data-index="${i}" ${!active||(G.turn===0&&(G.forbidden||[]).includes(MJ.base(t)))||declare&&!choices.includes(i)?'disabled':''} aria-pressed="${selected===i}"`)).join('');$('#hand').querySelectorAll('button').forEach(b=>b.onclick=()=>{let i=+b.dataset.index;if(selected===i){humanDiscard();return}selected=i;renderHand();renderActions()});$('#hand-info').textContent=p.riichi?'リーチ中 · 自動ツモ切り':declare?'リーチできる牌を選択':p.melds.some(m=>m.open)?'副露中 · 役が必要です':'門前 · 自動理牌'}
function humanDiscard(){if(selected<0)return;if(declare){if(!riichiChoices().includes(selected))return;G.players[0].riichi=true;G.players[0].ippatsu=true;G.players[0].score-=1000;G.pot++;log('あなたがリーチ');discard(selected,true)}else discard(selected)}
function renderActions(){let p=G.players[0];if(G.phase==='ron'){ronActions();return}if(G.phase==='result'){$('#status').textContent='この局が終了しました';$('#actions').innerHTML='<button id="result-open" class="quiet">結果を表示</button>';$('#result-open').onclick=showResult;return}if(G.phase!=='discard'||G.turn!==0){$('#status').textContent=seatPerson(G.turn).name+'の手番';$('#actions').innerHTML='<span class="waiting">次の一手を考えています…</span>';return}let r=G.afterCall?null:evaluate(0,true,p.hand.at(-1));$('#status').textContent=p.riichi?'リーチ中です':declare?'リーチ宣言：捨てる牌を選んでください':selected<0?'あなたの番です。捨てる牌を選んでください。':MJ.names[p.hand[selected]]+'を選択中';$('#actions').innerHTML=(r?'<button id="tsumo" class="accent">ツモ</button>':'')+(!p.riichi?`<button id="discard" class="primary" ${selected<0?'disabled':''}>${declare?'リーチして打牌':'打牌'}</button>`:'')+(!p.riichi&&riichiChoices().length?`<button id="riichi" class="quiet">${declare?'リーチを取り消す':'リーチ'}</button>`:'')+(p.riichi&&r?'<button id="decline-tsumo" class="quiet">和了を見送る</button>':'');if($('#tsumo'))$('#tsumo').onclick=()=>finishWin(0,0,p.hand.at(-1),r);if($('#discard'))$('#discard').onclick=humanDiscard;if($('#riichi'))$('#riichi').onclick=()=>{declare=!declare;selected=-1;renderHand();renderActions()};if($('#decline-tsumo'))$('#decline-tsumo').onclick=()=>discard(p.hand.length-1)}
window.addEventListener('beforeunload',()=>{if(G)save()});resumeButton();



